{"command": "cd .skilled/skills/sk-design/sk-design-md-generator/references && python3 - <<'PY'
import re, pathlib
files = ["color-role-taxonomy.md","component-taxonomy.md","creation-contract.md","design-knowledge/README.md","design-knowledge/anti-slop-principles.md","design-knowledge/cognitive-laws.md","design-knowledge/design-principles-digest.md","design-knowledge/design-token-vocabulary.md"]
for f in files:
    lines = pathlib.Path(f).read_text().splitlines()
    h1 = next((i for i,l in enumerate(lines) if re.match(r'^# ',l)), None)
    intro = []
    if h1 is not None:
        for l in lines[h1+1:]:
            if re.match(r'^#{1,6} ',l): break
            if l.strip() and not l.strip().startswith('>') and l.strip()!='---': intro.append(l.strip())
    h2 = [(i+1,l) for i,l in enumerate(lines) if re.match(r'^## ',l)]
    nums = [re.match(r'^## (\d+)\.',l).group(1) for _,l in h2 if re.match(r'^## (\d+)\.',l)]
    print(f"\n{f}: h1={h1+1 if h1 is not None else None} intro_lines={len(intro)} h2={[l for _,l in h2]}")
    print("  nums", nums, "sequential", nums==[str(i) for i in range(1,len(nums)+1)])
    if intro: print("  intro:", " ".join(intro)[:160])
PY"}
